package com.ecobridge.controller;
import com.ecobridge.entity.*; import com.ecobridge.repository.*; import jakarta.servlet.http.HttpSession; import jakarta.transaction.Transactional; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/communities") public class CommunityController {private final CommunityRepository communities;private final CommunityMemberRepository members;public CommunityController(CommunityRepository c,CommunityMemberRepository m){communities=c;members=m;}
 @GetMapping public List<Community> list(){return communities.findAll();}
 @Transactional @PostMapping @ResponseStatus(HttpStatus.CREATED) public Community create(@Valid @RequestBody Input in,HttpSession s){Long uid=user(s);Community c=new Community();c.setName(in.name().trim());c.setDescription(in.description());c.setLocality(in.locality());c.setCreatedBy(uid);c=communities.save(c);CommunityMember m=new CommunityMember();m.setCommunityId(c.getId());m.setUserId(uid);m.setRole("OWNER");members.save(m);return c;}
 @Transactional @PostMapping("/{id}/members") @ResponseStatus(HttpStatus.CREATED) public CommunityMember join(@PathVariable Long id,HttpSession s){Long uid=user(s);communities.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(members.findByCommunityIdAndUserId(id,uid).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Already a member");CommunityMember m=new CommunityMember();m.setCommunityId(id);m.setUserId(uid);return members.save(m);}
 private Long user(HttpSession s){Long id=(Long)s.getAttribute("userId");if(id==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return id;} public record Input(@NotBlank @Size(max=150) String name,@Size(max=4000) String description,@Size(max=255) String locality){}
}
